mapper.update:
{CALL
    DECLARE
        v_sql varchar2(500);
    BEGIN
        v_sql := 'CREATE INDEX ${tableName}_IDX1 ON ${tableName} (METADATA_HASH_CODE, EXP_DATE DESC)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX2 ON ${tableName} (IMG_STATUS, REQ_DATE)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX3 ON ${tableName} (IMG_STATUS, EXP_DATE)';
        execute immediate v_sql;
    END
}

UPDATE ${tableName}
SET
    IMG_STATUS = #{parameter.imageStatus}
    , METADATA_HASH_CODE = #{parameter.metadataHashCode}
    , IMG_PATH = #{parameter.imagePath}
    , FILE_URL = #{parameter.fileUrl}
    , REG_DATE = TO_DATE(#{parameter.registerDate}, 'YYYYMMDDHH24MISS')
    , EXP_DATE = TO_DATE(#{parameter.expireDate}, 'YYYYMMDDHH24MISS')
    , DONE_DATE = TO_DATE(#{parameter.doneDate}, 'YYYYMMDDHH24MISS')
    , DONE_CODE = #{parameter.doneCode}
    , DONE_CODE_DESC = #{parameter.doneCodeDescription}
WHERE
    IMG_KEY IS NULL
    IMG_KEY = #{parameter.key}
